import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  ChevronLeft, Calendar, User, MapPin, Clock, 
  MoreVertical, Search, Layers, ChevronDown, Plus, Minus,
  Monitor, X, Edit3, PlusSquare
} from 'lucide-react';
import './MeetingRoom.css';

const MeetingRoom = () => {
  const navigate = useNavigate();
  
  // --- 1. 获取实时基准时间 (严格校验的核心) ---
  const now = new Date();
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const currentHour = now.getHours();
  const currentMinute = now.getMinutes();

  // --- 2. 视图与流程控制 ---
  const [view, setView] = useState('list'); 
  const [selectedRoom, setSelectedRoom] = useState(null);
  const [attendees, setAttendees] = useState(0);
  const [activeTab, setActiveTab] = useState('All'); 
  const [openMenuId, setOpenMenuId] = useState(null);
  const [isEditing, setIsEditing] = useState(false); 

  // --- 3. 业务状态 (初始化日期设为今天) ---
  const [isCalendarOpen, setIsCalendarOpen] = useState(false);
  const [selectedDate, setSelectedDate] = useState(today); 
  const [viewDate, setViewDate] = useState(new Date(now.getFullYear(), now.getMonth(), 1)); 

  const [selectedStartTime, setSelectedStartTime] = useState('');
  const [selectedEndTime, setSelectedEndTime] = useState('');
  const [selectedDuration, setSelectedDuration] = useState('');
  const [selectedFloor, setSelectedFloor] = useState('');
  const [meetingTitle, setMeetingTitle] = useState('');
  const [appointmentType, setAppointmentType] = useState('');
  const [selectedParticipants, setSelectedParticipants] = useState([]);

  // 外部参与者弹窗状态
  const [isExtModalOpen, setIsExtModalOpen] = useState(false);
  const [extName, setExtName] = useState('');
  const [extEmail, setExtEmail] = useState('');

  // --- 4. 模拟数据 ---
  const meetingsData = [
    { id: 1, title: "UAT Briefing", host: "ALAN TAN WAI LOON", room: "Idea Lab 6", date: "2026-02-10", time: "12:00 PM - 12:30 PM", attendees: 1 },
    { id: 2, title: "Design Sync", host: "ALAN TAN WAI LOON", room: "Idea Lab 2", date: "2026-02-10", time: "02:00 PM - 03:00 PM", attendees: 3 },
    { id: 3, title: "Weekly Review", host: "ALAN TAN WAI LOON", room: "Idea Lab 5", date: "2026-02-12", time: "10:00 AM - 11:30 AM", attendees: 5 }
  ];

  const filteredMeetings = meetingsData.filter(meeting => {
    const dateStr = today.toISOString().split('T')[0];
    if (activeTab === 'Today') return meeting.date === dateStr;
    return true;
  });

  const allFeatures = ["Projector", "Interactive TV", "Non-Interactive TV", "180° Camera", "Conference Camera", "Tabletop Teams Panel", "Wireless Mic"];

  // --- 5. 动态时间过滤逻辑 (必须在当前时间之后) ---
  const getFilteredFromTimeSlots = () => {
    const isTodaySelected = selectedDate.toDateString() === today.toDateString();
    const slots = [];
    
    for (let hour = 10; hour <= 17; hour++) {
      const period = hour < 12 ? 'AM' : 'PM';
      const displayHour = hour > 12 ? hour - 12 : (hour === 0 ? 12 : hour);
      
      // 校验 :00
      if (!isTodaySelected || (hour > currentHour || (hour === currentHour && 0 > currentMinute))) {
        slots.push(`${displayHour}:00 ${period}`);
      }
      
      // 校验 :30 (17:30 不再允许作为起始时间)
      if (hour !== 17) {
        if (!isTodaySelected || (hour > currentHour || (hour === currentHour && 30 > currentMinute))) {
          slots.push(`${displayHour}:30 ${period}`);
        }
      }
    }
    return slots;
  };

  const fromTimeSlots = getFilteredFromTimeSlots();

  const getToTimeSlots = () => {
    if (!selectedStartTime) return [];
    const list = [];
    const [time, period] = selectedStartTime.split(' ');
    let [h, m] = time.split(':').map(Number);
    if (period === 'PM' && h !== 12) h += 12;
    if (period === 'AM' && h === 12) h = 0;
    const startNum = h + (m / 60) + 0.5;
    for (let i = startNum; i <= 20; i += 0.5) {
      const p = i < 12 ? 'AM' : 'PM';
      let dh = Math.floor(i);
      if (dh > 12) dh -= 12;
      const dm = (i % 1) === 0 ? "00" : "30";
      list.push(`${dh}:${dm} ${p}`);
    }
    return list;
  };

  const getAvailableDurations = () => {
    if (!selectedStartTime) return [];
    const [time, period] = selectedStartTime.split(' ');
    let [h, m] = time.split(':').map(Number);
    if (period === 'PM' && h !== 12) h += 12;
    if (period === 'AM' && h === 12) h = 0;
    const startNum = h + (m / 60);
    const maxAllowed = 20 - startNum; 
    const list = [];
    for (let i = 0.5; i <= Math.min(5, maxAllowed); i += 0.5) {
      const fH = Math.floor(i);
      const fM = (i % 1) * 60;
      list.push(i === 0.5 ? "30 min" : `${fH} hour${fH > 1 ? 's' : ''}${fM > 0 ? ' 30 min' : ''}`);
    }
    return list;
  };

  // --- 6. 交互逻辑 ---
  const handleBack = () => {
    if (view === 'form') {
      if (isEditing) { setView('list'); setIsEditing(false); }
      else setView('booking');
    }
    else if (view === 'booking') setView('results');
    else if (view === 'filter') setView('results');
    else if (view === 'results') setView('list');
    else navigate('/');
  };

  const handleEditClick = (meeting) => {
    setIsEditing(true);
    setMeetingTitle(meeting.title);
    setView('form');
    setOpenMenuId(null);
  };

  // 日历逻辑 (锁定过去日期)
  const changeMonth = (offset) => setViewDate(new Date(viewDate.getFullYear(), viewDate.getMonth() + offset, 1));
  
  const renderCalendarDays = () => {
    const year = viewDate.getFullYear();
    const month = viewDate.getMonth();
    const firstDay = new Date(year, month, 1).getDay();
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const startOffset = firstDay === 0 ? 6 : firstDay - 1;
    const days = [];
    
    for (let i = 0; i < startOffset; i++) days.push(<span key={`e-${i}`} className="day-empty"></span>);
    
    for (let d = 1; d <= daysInMonth; d++) {
      const cellDate = new Date(year, month, d);
      const isSelected = selectedDate.toDateString() === cellDate.toDateString();
      const isPast = cellDate < today; // 严格小于今天的日期
      
      days.push(
        <div 
          key={d} 
          className={`calendar-day ${isSelected ? 'selected' : ''} ${isPast ? 'past' : ''}`} 
          onClick={() => {
            if (!isPast) {
              setSelectedDate(cellDate);
              setSelectedStartTime(''); // 切换日期重置时间，防止逻辑漏洞
              setSelectedEndTime('');
            }
          }}
        >
          {d}
        </div>
      );
    }
    return days;
  };

  return (
    <div className="meeting-room-container">
      <nav className="top-nav-bar">
        <div className="back-arrow-wrapper" onClick={handleBack}><ChevronLeft size={24} color="#ffffff" strokeWidth={2.5} /></div>
        <span className="nav-title">
          {view === 'form' ? (isEditing ? "Edit Booking" : "Booking Detail") : (view === 'booking' ? "Meeting Room Details" : (view === 'filter' ? "Searching" : "Meeting Room"))}
        </span>
      </nav>

      <div className="scrollable-area">
        {view === 'list' && (
          <div className="content-padding">
            <div className="tabs-header">
              {['All', 'Today', 'Week'].map(tab => (
                <button key={tab} className={`tab ${activeTab === tab ? 'active' : ''}`} onClick={() => setActiveTab(tab)}>
                  {tab === 'All' ? 'List All' : tab}
                </button>
              ))}
            </div>
            <div className="summary-banner">
              <Calendar size={22} color="#1976d2" />
              <div className="summary-info">
                <h2 style={{fontSize: "13pt", fontWeight: "bold", margin: 0}}>{filteredMeetings.length} Meeting Upcoming</h2>
                <p style={{fontSize: "10pt", fontWeight: "bold", margin: "2px 0 0"}}>{today.toDateString()}</p>
              </div>
            </div>
            <div className="meeting-list">
              {filteredMeetings.map(meeting => (
                <div key={meeting.id} className="details-card">
                  <div className="card-top">
                    <h3>{meeting.title}</h3>
                    <div className="more-options-container">
                      <button className="more-options" onClick={() => setOpenMenuId(openMenuId === meeting.id ? null : meeting.id)}><MoreVertical size={20} color="#999" /></button>
                      {openMenuId === meeting.id && (
                        <div className="card-dropdown-menu">
                          <div className="dropdown-item" onClick={() => handleEditClick(meeting)}><Edit3 size={14} /> <span>Edit Booking</span></div>
                          <div className="dropdown-item delete" onClick={() => { alert('Cancelled'); setOpenMenuId(null); }}><X size={14} /> <span>Cancel Booking</span></div>
                        </div>
                      )}
                    </div>
                  </div>
                  <div className="info-rows">
                    <div className="row"><User size={18} className="icon" /><span>{meeting.host}</span></div>
                    <div className="row"><MapPin size={18} className="icon" /><span>{meeting.room}</span></div>
                    <div className="row"><Calendar size={18} className="icon" /><span>{meeting.date}</span></div>
                    <div className="row"><Clock size={18} className="icon" /><span>{meeting.time}</span></div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {view === 'filter' && (
          <div className="filter-form-wrapper">
            <p className="form-subtitle">Find A Meeting Room</p>
            <div className="field-group">
              <label>Date</label>
              <div className="form-field-box" onClick={() => setIsCalendarOpen(true)}>
                <span>{selectedDate.toISOString().split('T')[0]}</span>
                <Calendar size={18} color="#666" />
              </div>
            </div>
            <div className="field-group">
              <label>I need a meeting room from</label>
              <div className="form-field-box select-type">
                <select value={selectedStartTime} onChange={(e) => { setSelectedStartTime(e.target.value); setSelectedDuration(''); }}>
                  <option value="">{fromTimeSlots.length > 0 ? "Please Select Time" : "No available time today"}</option>
                  {fromTimeSlots.map(t => <option key={t} value={t}>{t}</option>)}
                </select>
                <ChevronDown size={18} className="select-arrow" />
              </div>
            </div>
            {/* ... 其它表单项保持不变 ... */}
            <div className="attendee-stepper">
              <label>Number of Attendees</label>
              <div className="stepper-controls">
                <button className="step-btn" onClick={() => setAttendees(Math.max(0, attendees - 1))}><Minus size={18} /></button>
                <span className="step-value">{attendees}</span>
                <button className="step-btn" onClick={() => setAttendees(Math.min(8, attendees + 1))}><Plus size={18} /></button>
              </div>
            </div>
            <button className="capsule-search-btn" onClick={() => setView('results')}>Search Room</button>
          </div>
        )}

        {/* --- 搜索结果、房间详情、预约表单等其它 View 保持原逻辑即可 --- */}
      </div>

      {/* --- Modals (日历弹窗) --- */}
      {isCalendarOpen && (
        <div className="calendar-overlay">
          <div className="calendar-modal">
            <div className="calendar-modal-header"><span>Calendar</span><button className="close-btn" onClick={() => setIsCalendarOpen(false)}>×</button></div>
            <div className="calendar-nav">
              <button className="nav-arrow" onClick={() => changeMonth(-1)}>{'<'}</button>
              <span className="month-year">{viewDate.toLocaleString('default', { month: 'long', year: 'numeric' })}</span>
              <button className="nav-arrow" onClick={() => changeMonth(1)}>{'>'}</button>
            </div>
            <div className="weekday-row">{['Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa', 'Su'].map(d => <span key={d}>{d}</span>)}</div>
            <div className="days-grid">{renderCalendarDays()}</div>
            <button className="calendar-confirm-btn" onClick={() => setIsCalendarOpen(false)}>CONFIRM</button>
          </div>
        </div>
      )}

      {/* 底部按钮逻辑 */}
      <div className="search-footer">
        {view === 'list' ? <button className="search-room-btn" onClick={() => setView('results')}><Search size={18} /> Search Room</button> 
        : view === 'form' ? <button className="book-room-btn" onClick={() => { setView('list'); alert('Confirmed'); }}>Confirm</button> : null}
      </div>
    </div>
  );
};

export default MeetingRoom;
